import{_ as t,o as a,c as s,ag as o}from"./chunks/framework.DFmy_ALI.js";const u=JSON.parse('{"title":"OpenWave OAuth Gateway","description":"","frontmatter":{},"headers":[],"relativePath":"guide/openwave-oauth-gateway.md","filePath":"guide/openwave-oauth-gateway.md"}'),n={name:"guide/openwave-oauth-gateway.md"};function i(r,e,d,c,l,p){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="openwave-oauth-gateway" tabindex="-1">OpenWave OAuth Gateway <a class="header-anchor" href="#openwave-oauth-gateway" aria-label="Permalink to &quot;OpenWave OAuth Gateway&quot;">​</a></h1><p>OpenWave OAuth is the scoped access layer for Astro, OpenWave Identity, Remote MCP, and future fintech apps.</p><p>OpenWave Identity issues tokens. Astro and Remote MCP validate those tokens as protected resources. Existing merchant keys, bank keys, and portal sessions remain supported.</p><h2 id="token-issuer" tabindex="-1">Token issuer <a class="header-anchor" href="#token-issuer" aria-label="Permalink to &quot;Token issuer&quot;">​</a></h2><p>OpenWave Identity owns:</p><ul><li>OAuth client registry.</li><li>client credentials.</li><li>token issuance.</li><li>token introspection and revocation.</li><li>global kill switches.</li><li>delegated consent and user/client grant revocation.</li></ul><p>Astro does not issue OpenWave ecosystem OAuth tokens.</p><h2 id="v1-grants" tabindex="-1">V1 grants <a class="header-anchor" href="#v1-grants" aria-label="Permalink to &quot;V1 grants&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Grant</th><th>Use</th></tr></thead><tbody><tr><td><code>client_credentials</code></td><td>Merchant backends, bank middleware, Neptune services, MCP clients.</td></tr><tr><td><code>refresh_token</code></td><td>Rotates delegated access tokens.</td></tr><tr><td><code>authorization_code</code> + PKCE</td><td>Delegated customer, bank, and operator approval through the Identity consent surface.</td></tr></tbody></table><h2 id="token-endpoint" tabindex="-1">Token endpoint <a class="header-anchor" href="#token-endpoint" aria-label="Permalink to &quot;Token endpoint&quot;">​</a></h2><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /v1/oauth/token</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Type</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/x-www-form-urlencoded</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">grant_type=client_credentials&amp;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">client_id=owc_...&amp;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">client_secret=ows_...&amp;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scope=astro:merchant.reports.read openwave:mcp.read&amp;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">audience=astro&amp;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">environment=SANDBOX</span></span></code></pre></div><p>The response contains a bearer access token and refresh token. Keep both server-side.</p><h2 id="authorization-code-endpoint" tabindex="-1">Authorization-code endpoint <a class="header-anchor" href="#authorization-code-endpoint" aria-label="Permalink to &quot;Authorization-code endpoint&quot;">​</a></h2><p>Delegated clients start at Identity:</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /v1/oauth/authorize?response_type=code&amp;client_id=owc_...&amp;redirect_uri=https%3A%2F%2Fapp.example%2Fcallback&amp;scope=openwave%3Amcp.read&amp;state=...&amp;code_challenge=...&amp;code_challenge_method=S256</span></span></code></pre></div><p>Identity validates exact redirect URI, owner/environment gates, requested scopes, and PKCE <code>S256</code>. The customer, bank, or operator reviews the request in <code>/portal/oauth-consent</code>. The one-time code is exchanged at <code>/v1/oauth/token</code> and replay is rejected.</p><h2 id="astro-resource-access" tabindex="-1">Astro resource access <a class="header-anchor" href="#astro-resource-access" aria-label="Permalink to &quot;Astro resource access&quot;">​</a></h2><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/merchant/integration</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer owat_...</span></span></code></pre></div><p>Astro accepts Identity-issued OAuth tokens only when:</p><ul><li>OAuth is enabled.</li><li>the token is active by Identity introspection.</li><li>Astro is configured with a resource-server OAuth client.</li><li>the client is active.</li><li>the token environment is enabled.</li><li>the owner type is enabled.</li><li>the required scope is present.</li><li>the tenant in the token matches the requested resource.</li></ul><p>When <code>OPENWAVE_OAUTH_ENABLED=true</code>, Astro uses <code>OPENWAVE_OAUTH_INTROSPECTION_CLIENT_ID</code> and <code>OPENWAVE_OAUTH_INTROSPECTION_CLIENT_SECRET</code> for Basic-authenticated introspection. Missing credentials fail closed.</p><p>Astro also applies a bounded per-source-IP bearer-token rate limit before token-shape checks and Identity introspection. Defaults are <code>OPENWAVE_OAUTH_BEARER_RATE_LIMIT_PER_MINUTE=120</code> and <code>OPENWAVE_OAUTH_BEARER_RATE_LIMIT_MAX_ENTRIES=20000</code>; exceeded requests return local <code>429</code> without calling Identity.</p><h2 id="recommended-scopes" tabindex="-1">Recommended scopes <a class="header-anchor" href="#recommended-scopes" aria-label="Permalink to &quot;Recommended scopes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Purpose</th></tr></thead><tbody><tr><td><code>astro:payments.create</code></td><td>Create payment sessions.</td></tr><tr><td><code>astro:payments.read</code></td><td>Read payment/session status.</td></tr><tr><td><code>astro:merchant.reports.read</code></td><td>Merchant-scoped reports.</td></tr><tr><td><code>astro:merchant.webhooks.manage</code></td><td>Merchant webhook management.</td></tr><tr><td><code>astro:bank.reports.read</code></td><td>Bank-scoped reports.</td></tr><tr><td><code>openwave:mcp.read</code></td><td>Remote MCP read tools.</td></tr><tr><td><code>openwave:mcp.write</code></td><td>Remote MCP write tools, still blocked unless mutation switch is enabled.</td></tr><tr><td><code>openwave:owner.ops.read</code></td><td>Neptune owner operations overview and incident reports.</td></tr><tr><td><code>openwave:tokens.introspect</code></td><td>Resource-server clients only; permits protected resources to introspect tokens.</td></tr></tbody></table><h2 id="remote-mcp" tabindex="-1">Remote MCP <a class="header-anchor" href="#remote-mcp" aria-label="Permalink to &quot;Remote MCP&quot;">​</a></h2><p>Astro Remote MCP is protected by Identity OAuth and remains read-only in v1. The remote tools include <code>astro_oauth_readiness</code>, which reports protected-resource metadata, flag posture, Identity metadata reachability, credential presence, and the tokenless <code>/mcp</code> protection result without exposing secrets.</p><p>To validate a deployment, operators should prove:</p><ol><li>Tokenless <code>POST /mcp</code> returns controlled protection, not tool access.</li><li>An Identity-issued token with <code>openwave:mcp.read</code> and <code>openwave:owner.ops.read</code> can call <code>initialize</code>, <code>tools/list</code>, and <code>tools/call</code> for <code>astro_oauth_readiness</code>.</li><li>Mutation tools remain unavailable unless a future review enables <code>openwave:mcp.write</code> and <code>mcp.mutations</code>.</li></ol><h2 id="backward-compatibility" tabindex="-1">Backward compatibility <a class="header-anchor" href="#backward-compatibility" aria-label="Permalink to &quot;Backward compatibility&quot;">​</a></h2><p>Existing raw merchant keys and bank keys are not removed. OAuth is additive so partners can migrate without breaking current integrations.</p>`,30)])])}const k=t(n,[["render",i]]);export{u as __pageData,k as default};
